// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.util.Map;
import java.util.Set;

import org.eclipse.rdf4j.common.order.AvailableStatementOrder;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.algebra.helpers.QueryAlgebraBindingAnalysis;
import org.eclipse.rdf4j.query.algebra.helpers.TupleExprs;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

class GraphTest {

	@Test
	void ownsAndClonesBothChildren() {
		Graph graph = new Graph(Var.of("g"), new SingletonSet());
		assertThat(graph.getBindingNames()).containsExactly("g");
		assertThat(graph.getAssuredBindingNames()).containsExactly("g");
		Graph clone = graph.clone();
		assertThat(clone).isEqualTo(graph).hasSameHashCodeAs(graph);
		assertNotSame(graph.getGraphName(), clone.getGraphName());
		assertNotSame(graph.getArg(), clone.getArg());
		assertSame(clone, clone.getGraphName().getParentNode());
		assertSame(clone, clone.getArg().getParentNode());
		clone.getGraphName().replaceWith(Var.of("h"));
		assertThat(clone.getBindingNames()).containsExactly("h");
		assertThat(clone).isNotEqualTo(graph);
	}

	@Test
	void serializesItsGraphNameAndBody() throws Exception {
		Graph graph = new Graph(Var.of("g"), new SingletonSet());
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(graph);
		}
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			Graph restored = (Graph) input.readObject();
			assertThat(restored).isEqualTo(graph);
			assertSame(restored, restored.getGraphName().getParentNode());
			assertSame(restored, restored.getArg().getParentNode());
		}
	}

	@Test
	void defaultVisitorRetainsForeignNodeCompatibility() {
		Graph graph = new Graph(Var.of("g"), new SingletonSet());
		int[] count = { 0 };
		graph.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meetOther(QueryModelNode node) {
				if (node instanceof Graph) {
					count[0]++;
				}
				super.meetOther(node);
			}
		});
		assertThat(count[0]).isEqualTo(1);
	}

	@Test
	void graphBoundarySurvivesWrappersAndStopsAtService() {
		Graph graph = new Graph(Var.of("g"), new SingletonSet());
		assertThat(TupleExprs.requiresIndependentEvaluation(new Filter(graph, new Bound(Var.of("g"))))).isTrue();
		Service service = new Service(
				TupleExprs.createConstVar(SimpleValueFactory.getInstance().createIRI("urn:service")),
				graph, "GRAPH ?g {}", Map.of(), null, false);
		assertThat(TupleExprs.containsGraphBoundary(service)).isFalse();
	}

	@Test
	void selectedNameIsGuaranteedAfterBodyAndAbsentFromBodyInput() {
		Graph graph = new Graph(Var.of("g"), new SingletonSet());
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(graph,
				EmptyBindingSet.getInstance());
		assertThat(analysis.contextAt(graph.getArg()).maybeBoundNames()).isEmpty();
		assertThat(analysis.outputFacts(graph, analysis.rootContext()).guaranteedOutputs()).containsExactly("g");
	}

	@Test
	void variableGraphDoesNotAdvertisePerGraphChildOrdering() {
		Var ordered = Var.of("s");
		StatementPattern child = new StatementPattern(ordered, Var.of("p"), Var.of("o")) {
			@Override
			public Set<Var> getSupportedOrders(AvailableStatementOrder source) {
				return Set.of(ordered);
			}
		};
		Graph graph = new Graph(Var.of("g"), child);
		assertThat(graph.getSupportedOrders(null)).isEmpty();
		assertThrows(UnsupportedOperationException.class, () -> graph.setOrder(ordered));
	}

	@Test
	void constantGraphDoesNotAdvertiseOrdersForTheWrongPhysicalContext() {
		Var ordered = Var.of("s");
		StatementPattern child = new StatementPattern(ordered, Var.of("p"), Var.of("o")) {
			@Override
			public Set<Var> getSupportedOrders(AvailableStatementOrder source) {
				// This models a backend whose all-context scan has an order unavailable in a selected context.
				return Set.of(ordered);
			}
		};
		Graph graph = new Graph(TupleExprs.createConstVar(SimpleValueFactory.getInstance().createIRI("urn:g")),
				new Filter(child, new Bound(Var.of("o"))));
		assertThat(graph.getSupportedOrders(null)).isEmpty();
		assertThrows(UnsupportedOperationException.class, () -> graph.setOrder(ordered));
		assertThat(graph.getOrder()).isNull();
	}
}
